<?php
require_once __DIR__.'/config.php'; require_auth(['admin','employee']); require_permission('manage_inventory'); ensure_extended_schema(); $pdo=db();$error='';$flash=get_flash();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='save'){ $n=trim($_POST['name']??'');$q=max(0,(int)($_POST['quantity']??0));$min=max(0,(int)($_POST['min_quantity']??0));$buy=(float)($_POST['purchase_price']??0);$sale=(float)($_POST['sale_price']??0);if($n==='')$error='اسم القطعة مطلوب.';else{if($id){$old=$pdo->prepare("SELECT * FROM inventory_parts WHERE id=:id");$old->execute([':id'=>$id]);$ov=$old->fetch();$pdo->prepare("UPDATE inventory_parts SET name=:n,quantity=:q,min_quantity=:m,purchase_price=:b,sale_price=:s WHERE id=:id")->execute([':n'=>$n,':q'=>$q,':m'=>$min,':b'=>$buy,':s'=>$sale,':id'=>$id]);log_audit_change('edit','inventory_parts',$id,'تعديل قطعة غيار',json_encode($ov,JSON_UNESCAPED_UNICODE),json_encode(['name'=>$n,'quantity'=>$q,'min_quantity'=>$min,'purchase_price'=>$buy,'sale_price'=>$sale],JSON_UNESCAPED_UNICODE));}else{$pdo->prepare("INSERT INTO inventory_parts(name,quantity,min_quantity,purchase_price,sale_price) VALUES(:n,:q,:m,:b,:s)")->execute([':n'=>$n,':q'=>$q,':m'=>$min,':b'=>$buy,':s'=>$sale]);log_audit('add','inventory_parts',(int)$pdo->lastInsertId(),'إضافة قطعة غيار: '.$n);}set_flash('success','تم حفظ القطعة.');header('Location: inventory.php');exit;}}elseif($a==='delete'&&$id){$pdo->prepare("DELETE FROM inventory_parts WHERE id=:id")->execute([':id'=>$id]);log_audit('delete','inventory_parts',$id,'حذف قطعة غيار');set_flash('success','تم حذف القطعة.');header('Location: inventory.php');exit;}}
$parts=$pdo->query("SELECT * FROM inventory_parts ORDER BY id DESC")->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>المخزون</title><link rel="stylesheet" href="style.css"></head><body class="dashboard-body"><div class="dashboard-wrapper"><main class="main-content" style="width:100%"><header class="topbar"><h2 class="page-title">🔧 قطع الغيار والمخزون</h2><a class="btn btn-outline" href="dashboard.php">العودة</a></header><div class="content-container"><?php if($flash):?><div class="alert alert-<?=clean($flash['type'])?>"><?=clean($flash['message'])?></div><?php endif;?><div class="card mb-4"><div class="card-body"><form method="post" class="form-grid" style="grid-template-columns:repeat(auto-fit,minmax(160px,1fr))"><?=csrf_field()?><input type="hidden" name="action" value="save"><input class="form-control" name="name" placeholder="اسم القطعة" required><input class="form-control" type="number" name="quantity" min="0" placeholder="الكمية"><input class="form-control" type="number" name="min_quantity" min="0" placeholder="الحد الأدنى"><input class="form-control" type="number" step="0.01" name="purchase_price" placeholder="سعر الشراء"><input class="form-control" type="number" step="0.01" name="sale_price" placeholder="سعر البيع"><button class="btn btn-primary">إضافة قطعة</button></form></div></div><div class="card"><div class="card-body" style="overflow-x:auto"><table class="data-table"><thead><tr><th>القطعة</th><th>الكمية</th><th>الحد الأدنى</th><th>الشراء</th><th>البيع</th><th>الحالة</th><th></th></tr></thead><tbody><?php foreach($parts as $x):?><tr><td><?=clean($x['name'])?></td><td><?=($x['quantity']<=$x['min_quantity']?'<span class="badge badge-danger">':'')?><?=intval($x['quantity'])?><?=($x['quantity']<=$x['min_quantity']?'</span>':'')?></td><td><?=intval($x['min_quantity'])?></td><td><?=format_money($x['purchase_price'])?></td><td><?=format_money($x['sale_price'])?></td><td><?=status_badge($x['status'])?></td><td><form method="post" onsubmit="return confirm('حذف القطعة؟')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn btn-sm btn-outline-danger">حذف</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></main></div></body></html>